CREATE TABLE field_effect_actions (action_id TEXT PRIMARY KEY NOT NULL CHECK(action_id GLOB 'effect_action_[0-9a-f]*' AND length(action_id)=78), plan_id TEXT NOT NULL REFERENCES field_effects(plan_id), kind TEXT NOT NULL CHECK(kind IN ('targeted_read','forward_reevaluation')), state TEXT NOT NULL CHECK(state IN ('pending','claimed','completed')), attempt INTEGER NOT NULL CHECK(attempt BETWEEN 0 AND 3), updated_at INTEGER NOT NULL CHECK(updated_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 8192), UNIQUE(plan_id,kind));
CREATE TABLE field_effect_authorities (decision_id TEXT PRIMARY KEY NOT NULL, current INTEGER NOT NULL CHECK(current IN (0,1)), updated_at INTEGER NOT NULL CHECK(updated_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 4096));
CREATE TABLE field_effect_cleanups (plan_id TEXT PRIMARY KEY NOT NULL REFERENCES field_effects(plan_id), state TEXT NOT NULL CHECK(state IN ('pending','completed')), attempt INTEGER NOT NULL CHECK(attempt BETWEEN 0 AND 3), updated_at INTEGER NOT NULL CHECK(updated_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 4096));
