CREATE TABLE review_preparation_scans (scan_id TEXT PRIMARY KEY NOT NULL CHECK(scan_id GLOB 'review_scan_[0-9a-f]*' AND length(scan_id)=76), connection_name TEXT NOT NULL, library_name TEXT NOT NULL, library_id TEXT NOT NULL, producer_fingerprint TEXT NOT NULL CHECK(length(producer_fingerprint)=64 AND producer_fingerprint NOT GLOB '*[^0-9a-f]*'), state TEXT NOT NULL CHECK(state IN ('queued','discovering','processing','completed','completed_with_failures')), requested_at INTEGER NOT NULL CHECK(requested_at>=0), updated_at INTEGER NOT NULL CHECK(updated_at>=requested_at), catalogue_generation INTEGER CHECK(catalogue_generation IS NULL OR catalogue_generation>0), catalogue_fingerprint TEXT CHECK(catalogue_fingerprint IS NULL OR (length(catalogue_fingerprint)=64 AND catalogue_fingerprint NOT GLOB '*[^0-9a-f]*')), qualification_epoch INTEGER CHECK(qualification_epoch IS NULL OR qualification_epoch>=0), total INTEGER NOT NULL DEFAULT 0 CHECK(total>=0), refresh_count INTEGER NOT NULL DEFAULT 0 CHECK(refresh_count BETWEEN 0 AND 3), rescan_requested INTEGER NOT NULL DEFAULT 0 CHECK(rescan_requested IN (0,1)));
CREATE TABLE review_preparation_work (work_id TEXT PRIMARY KEY NOT NULL CHECK(work_id GLOB 'review_work_[0-9a-f]*' AND length(work_id)=76), scan_id TEXT NOT NULL REFERENCES review_preparation_scans(scan_id) ON DELETE CASCADE, ordinal INTEGER NOT NULL CHECK(ordinal>=0), connection_name TEXT NOT NULL, library_name TEXT NOT NULL, library_id TEXT NOT NULL, item_id TEXT NOT NULL, file_identity TEXT NOT NULL CHECK(length(file_identity)=64 AND file_identity NOT GLOB '*[^0-9a-f]*'), source_revision INTEGER NOT NULL CHECK(source_revision>=0), source_fingerprint TEXT NOT NULL CHECK(length(source_fingerprint)=64 AND source_fingerprint NOT GLOB '*[^0-9a-f]*'), producer_fingerprint TEXT NOT NULL CHECK(length(producer_fingerprint)=64 AND producer_fingerprint NOT GLOB '*[^0-9a-f]*'), catalogue_generation INTEGER NOT NULL CHECK(catalogue_generation>0), catalogue_fingerprint TEXT NOT NULL CHECK(length(catalogue_fingerprint)=64 AND catalogue_fingerprint NOT GLOB '*[^0-9a-f]*'), stage TEXT NOT NULL CHECK(stage IN ('extraction','provider','proposal','admission','projection','complete')), state TEXT NOT NULL CHECK(state IN ('queued','delayed','running','complete','failed','stale')), attempt INTEGER NOT NULL DEFAULT 0 CHECK(attempt BETWEEN 0 AND 3), recovery_attempt INTEGER NOT NULL DEFAULT 0 CHECK(recovery_attempt BETWEEN 0 AND 3), retry_not_before INTEGER NOT NULL DEFAULT 0 CHECK(retry_not_before>=0), report_id TEXT REFERENCES metadata_reports(report_id), recovery_source_report_id TEXT REFERENCES metadata_reports(report_id), proposal_set_id TEXT REFERENCES proposal_sets(proposal_set_id), review_case_id TEXT REFERENCES review_cases(review_case_id), outcome TEXT CHECK(outcome IS NULL OR outcome IN ('case','no_case','evidence_only')), failure_code TEXT CHECK(failure_code IS NULL OR failure_code IN ('provider','configuration','authentication','stale','transient','projection','failed','currentness','persistence','unsupported_media','unreadable_media','parser_refused','multi_file_budget_exceeded','missing_required_input','malformed_retained_data','internal_failure','unknown')), failure_root TEXT CHECK(failure_root IS NULL OR (typeof(failure_root)='text' AND length(CAST(failure_root AS BLOB)) BETWEEN 1 AND 64 AND ((failure_code='authentication' AND failure_root NOT GLOB '*[^a-z0-9_-]*' AND substr(failure_root,1,1) GLOB '[a-z]') OR (failure_code IN ('unsupported_media','unreadable_media','parser_refused','multi_file_budget_exceeded') AND (failure_root GLOB 'track_[1-9]' OR failure_root GLOB 'track_[1-9][0-9]' OR failure_root GLOB 'track_[1-9][0-9][0-9]'))))), presentation_recovery_cycle_id TEXT CHECK(presentation_recovery_cycle_id IS NULL OR (presentation_recovery_cycle_id GLOB 'preparation_cycle_[0-9a-f]*' AND length(presentation_recovery_cycle_id)=82)), presentation_recovery_stage TEXT CHECK(presentation_recovery_stage IS NULL OR presentation_recovery_stage IN ('extraction','provider','proposal','admission','projection')), presentation_recovery_outcome TEXT CHECK(presentation_recovery_outcome IS NULL OR presentation_recovery_outcome IN ('ready','failed')), updated_at INTEGER NOT NULL CHECK(updated_at>=0), CHECK((presentation_recovery_cycle_id IS NULL AND presentation_recovery_stage IS NULL AND presentation_recovery_outcome IS NULL) OR (presentation_recovery_cycle_id IS NOT NULL AND presentation_recovery_stage IS NOT NULL)), CHECK((state='complete')=(outcome IS NOT NULL)), CHECK(outcome IS NULL OR (outcome='case' AND review_case_id IS NOT NULL) OR (outcome='no_case' AND proposal_set_id IS NOT NULL AND review_case_id IS NULL) OR (outcome='evidence_only' AND report_id IS NOT NULL AND proposal_set_id IS NULL AND review_case_id IS NULL)), UNIQUE(scan_id,item_id));
