CREATE TRIGGER metadata_report_cover_references_no_update BEFORE UPDATE ON metadata_report_cover_references BEGIN SELECT RAISE(ABORT, 'metadata report cover references are append-only'); END;
CREATE TRIGGER metadata_report_cover_references_no_delete BEFORE DELETE ON metadata_report_cover_references BEGIN SELECT RAISE(ABORT, 'metadata report cover references are append-only'); END;
